    z_t2558_t _r;
    if (idx >= 0) {
        _r.tag = Z_OPTIONVAL_FOLDEDBRANCH_TAG_SOME;
        _r.data.some = _this->entries[idx].value;
    } else {
        _r.tag = Z_OPTIONVAL_FOLDEDBRANCH_TAG_NONE;
    }
    return _r;
